import os
import torch

# -----------------------------------------------------------------------------
# 1. Directory & File Paths
# -----------------------------------------------------------------------------
# Base Input Directory
INPUT_DIR = "./input"

# Metadata Paths (Generated by the metadata script)
METADATA_DIR = "./metadata"
TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val.csv")
TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")
SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")

# Working Directory for Outputs (Cache, Models, Logs)
# Using specific idea folder as requested
WORKING_DIR = "./working/idea_36"
os.makedirs(WORKING_DIR, exist_ok=True)

# Cache Paths for Deterministic Data Processing
TRAIN_CACHE_PATH = os.path.join(WORKING_DIR, "train_cache.parquet")
VAL_CACHE_PATH = os.path.join(WORKING_DIR, "val_cache.parquet")
TEST_CACHE_PATH = os.path.join(WORKING_DIR, "test_cache.parquet")

# Model Save Path
MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")

# Submission Output
SUBMISSION_DIR = "./submission"
os.makedirs(SUBMISSION_DIR, exist_ok=True)
SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

# -----------------------------------------------------------------------------
# 2. Data Hyperparameters
# -----------------------------------------------------------------------------
# Image Geometry
IMG_SIZE = 224
INTERPOLATION = "area"  # cv2.INTER_AREA

# Stack Construction
# 4 Groups: FLAIR, T1w, T1wCE, T2w
# Each group has NUM_SLICES slices
NUM_SLICES = 3
STRIDE = 5
TOTAL_SLICES = NUM_SLICES * 4  # 12 channels total
INPUT_CHANNELS = 12

# ROI Selection (Fidelity-Aligned)
# Restrict search to 15% - 85% of volume depth
ROI_DEPTH_RANGE = (0.15, 0.85)
ROI_ANCHOR_MODALITY = "FLAIR"

# -----------------------------------------------------------------------------
# 3. Model Hyperparameters
# -----------------------------------------------------------------------------
BACKBONE = "efficientnet_b0"
PRETRAINED = True
DROPOUT_RATE = 0.5
NUM_CLASSES = 1

# -----------------------------------------------------------------------------
# 4. Training Hyperparameters
# -----------------------------------------------------------------------------
SEED = 42
BATCH_SIZE = 32
NUM_EPOCHS = 20

# Optimizer Settings
LEARNING_RATE = 1e-4
WEIGHT_DECAY = 1e-2  # Aggressive weight decay

# Early Stopping
EARLY_STOPPING_PATIENCE = 5
EARLY_STOPPING_MIN_DELTA = 0.0001

# -----------------------------------------------------------------------------
# 5. Augmentation & Inference
# -----------------------------------------------------------------------------
# Augmentation
AUG_ROTATION_DEGREES = 15
AUG_REFLECTION_PADDING = True
AUG_HFLIP_PROB = 0.5
AUG_VFLIP_PROB = 0.5

# Test Time Augmentation (TTA)
# Options: "original", "hflip", "vflip"
TTA_STRATEGIES = ["original", "hflip", "vflip"]

# -----------------------------------------------------------------------------
# 6. Compute Configuration
# -----------------------------------------------------------------------------
DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
NUM_WORKERS = 12  # Utilizing available vCPUs
PIN_MEMORY = True if DEVICE == "cuda" else False
